package com.bank.dbx;

import java.util.logging.Logger;

// Wraps Spark with the Databricks Runtime: tuned engine (Photon), autoscaling, auto-termination.
class DatabricksRuntime {
    private static final Logger log = Logger.getLogger(DatabricksRuntime.class.getName());

    private final SparkEngine engine;      // still real Spark underneath
    private final boolean photon;
    private final int minWorkers;
    private final int maxWorkers;
    private boolean clusterRunning = false;
    private int currentWorkers;

    DatabricksRuntime(SparkEngine engine, boolean photon, int minWorkers, int maxWorkers) {
        this.engine = engine;
        this.photon = photon;
        this.minWorkers = minWorkers;
        this.maxWorkers = maxWorkers;
    }

    // Autoscales up for heavy work, runs on the tuned runtime, reports the speedup.
    double runJob(String name, double workUnits) {
        startIfNeeded();
        autoscale(workUnits);
        double raw = engine.runJob(name, workUnits);
        double factor = photon ? 0.4 : 0.8;   // Photon vectorized engine ~2.5x faster
        double seconds = raw * factor;
        log.info(() -> "[Databricks] '" + name + "' ran in " + seconds + "s on "
                + currentWorkers + " autoscaled workers (Photon=" + photon + ")");
        return seconds;
    }

    private void startIfNeeded() {
        if (!clusterRunning) {
            clusterRunning = true;
            currentWorkers = minWorkers;
            log.info(() -> "Cluster auto-started with " + minWorkers + " workers");
        }
    }

    private void autoscale(double workUnits) {
        int target = (int) Math.min(maxWorkers, Math.max(minWorkers, Math.ceil(workUnits / 100.0)));
        if (target != currentWorkers) {
            log.info(() -> "Autoscaling from " + currentWorkers + " to " + target + " workers");
            currentWorkers = target;
        }
    }

    void autoTerminateIfIdle(int idleMinutes, int threshold) {
        if (idleMinutes >= threshold && clusterRunning) {
            clusterRunning = false;
            log.info(() -> "Cluster auto-terminated after " + idleMinutes + " idle minutes (saves cost)");
        }
    }
}
