package com.bank.dbx;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// A Delta table: versioned snapshots give ACID writes + time travel.
class DeltaTable {
    private static final Logger log = Logger.getLogger(DeltaTable.class.getName());

    private final String name;
    private final List<List<String>> versions = new ArrayList<>(); // each version = full snapshot

    DeltaTable(String name) {
        this.name = name;
        versions.add(new ArrayList<>()); // version 0: empty
    }

    // Atomic write: creates a new committed version (transaction log entry).
    int write(List<String> rows) {
        List<String> snapshot = new ArrayList<>(current());
        snapshot.addAll(rows);
        versions.add(snapshot);
        int v = versions.size() - 1;
        log.info(() -> "Delta '" + name + "' committed version " + v + " (" + snapshot.size() + " rows) atomically");
        return v;
    }

    List<String> current() { return versions.get(versions.size() - 1); }

    // Time travel: read an older committed version.
    List<String> versionAsOf(int v) {
        log.info(() -> "Time travel: reading '" + name + "' VERSION AS OF " + v);
        return versions.get(v);
    }
}
