package com.bank.dbx;

import java.util.Set;
import java.util.logging.Logger;

// Hosts notebooks, the Delta lakehouse, and Unity-Catalog-style governance.
class ManagedWorkspace {
    private static final Logger log = Logger.getLogger(ManagedWorkspace.class.getName());

    private final DatabricksRuntime runtime;
    private final Set<String> authorizedUsers;
    private final boolean enforceAccessControl;

    ManagedWorkspace(DatabricksRuntime runtime, Set<String> authorizedUsers, boolean enforceAccessControl) {
        this.runtime = runtime;
        this.authorizedUsers = authorizedUsers;
        this.enforceAccessControl = enforceAccessControl;
    }

    // Runs a notebook cell as a user, enforcing governance before touching data.
    void runNotebookCell(String user, String cellName, double workUnits, DeltaTable table) {
        if (enforceAccessControl && !authorizedUsers.contains(user)) {
            log.warning(() -> "Unity Catalog DENIED " + user + " access to " + cellName);
            return;
        }
        log.info(() -> "Notebook cell '" + cellName + "' run by " + user + " (governed access granted)");
        runtime.runJob(cellName, workUnits);
    }
}
