package com.bank.dbx;

import java.util.List;
import java.util.Set;
import java.util.logging.Logger;

public class DatabricksDemo {
    private static final Logger log = Logger.getLogger(DatabricksDemo.class.getName());

    public static void main(String[] args) {
        SparkEngine oss = new SparkEngine();

        // Same logical job on OSS Spark vs Databricks Runtime.
        log.info("=== Same Spark job: OSS vs Databricks ===");
        oss.runJob("daily_trade_aggregation", 400);
        DatabricksRuntime runtime = new DatabricksRuntime(new SparkEngine(), true, 2, 8);
        runtime.runJob("daily_trade_aggregation", 400);
        runtime.autoTerminateIfIdle(30, 30);

        // Governed notebook + transactional Delta write + time travel.
        log.info("=== Governed lakehouse with Delta ===");
        ManagedWorkspace ws = new ManagedWorkspace(runtime,
                Set.of("priya_analyst", "rajesh_engineer"), true);
        DeltaTable trades = new DeltaTable("trades");

        ws.runNotebookCell("rajesh_engineer", "ingest_trades", 200, trades);
        int v1 = trades.write(List.of("TRD-1,SAV2001,50000", "TRD-2,CUR3001,80000"));
        int v2 = trades.write(List.of("TRD-3,SAV2001,30000"));
        log.info(() -> "Current trades rows = " + trades.current().size());
        log.info(() -> "Time-travel to version " + v1 + " rows = " + trades.versionAsOf(v1).size());

        // Unauthorized access is blocked by governance.
        ws.runNotebookCell("unknown_contractor", "read_pii", 10, trades);
    }
}
